  if (!activeBook || books.length === 0) return;

  const currentBook = books.find(
    (b) =>
      b.namePt.toLowerCase() === activeBook.toLowerCase() ||
      b.nameEn.toLowerCase() === activeBook.toLowerCase() ||
      b.abbreviation.toLowerCase() === activeBook.toLowerCase()
  );

