260:   const startMarker = /\*\*\* START OF (THE|THIS) PROJECT GUTENBERG/i;
261:   const endMarker = /\*\*\* END OF (THE|THIS) PROJECT GUTENBERG/i;
262:   const startIdx = text.search(startMarker);
263:   const endIdx = text.search(endMarker);
264:   if (startIdx > -1) text = text.slice(startIdx + 100);
265:   if (endIdx > -1) text = text.slice(0, endIdx);
266:   return text.trim();
