49:  * Quantas páginas o PDF tem, segundo o que a lib devolveu.
50:  *
51:  * Existe como função separada — e testada — porque o nome do campo mudou entre
52:  * as versões do `pdf-parse` e a troca passou despercebida. Na v1 era
53:  * `numpages`; na v2 (`PDFParse.getText()` → `TextResult`) é `total`, e `pages`
54:  * virou o array de páginas. Ler `numpages` de um TextResult devolve
55:  * `undefined` sem erro nenhum.
56:  *
57:  * O silêncio é o problema: `meta.pages` alimenta o guarda de PDF escaneado do
58:  * analyze-quality ("menos de 400 caracteres por página → precisa de OCR").
59:  * Com `undefined`, a divisão dá Infinity, o guarda nunca dispara e um PDF
60:  * escaneado com 6.776 caracteres de camada de texto passa com nota 97 — foi o
61:  * que aconteceu com "A Arte e a Bíblia" (Schaeffer), indexada com 34 trechos.
62:  *
63:  * Devolve `undefined` só quando a informação realmente não veio, para o
64:  * chamador poder distinguir "não sei" de "sei que é pequeno".
65:  */
66: export function pdfPageCount(pdfData: unknown): number | undefined {
67:   const d = pdfData as {
68:     total?: unknown;
69:     numpages?: unknown;
70:     pages?: unknown;
71:   };
72: 
73:   // v2: TextResult.total
74:   if (typeof d?.total === 'number' && Number.isFinite(d.total)) return d.total;
75:   // v1: numpages
76:   if (typeof d?.numpages === 'number' && Number.isFinite(d.numpages)) {
77:     return d.numpages;
78:   }
79:   // Último recurso: o array de páginas da v2.
80:   if (Array.isArray(d?.pages)) return d.pages.length;
81:   return undefined;
82: }
83: 
84: const pdfExtractor: Extractor = {
85:   canHandle: (mime) => mime === 'application/pdf',
86:   async extract(buffer) {
87:     const parser = new pdfParse.PDFParse(new Uint8Array(buffer));
88:     const pdfData = await parser.getText();
89:     return {
90:       text: pdfData.text ?? '',
91:       meta: { pages: pdfPageCount(pdfData) },
92:     };
93:   },
94: };
95: 
96: /* ─── DOCX ─────────────────────────────────────────────────────────────── */
97: 
98: const docxExtractor: Extractor = {
99:   canHandle: (mime) =>
100:     mime ===
101:     'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
102:   async extract(buffer) {
103:     const result = await mammoth.extractRawText({ buffer });
104:     return { text: result.value ?? '' };
105:   },
106: };
107: 
108: /* ─── EPUB ─────────────────────────────────────────────────────────────── */
109: 
110: /**
111:  * Mime types Google Drive reports for EPUB files. There's no single
112:  * canonical type — Drive sometimes uses `application/epub+zip` (IANA)
113:  * and sometimes `application/octet-stream` for legacy uploads.
114:  */
115: const EPUB_MIMES = new Set(['application/epub+zip', 'application/epub']);
116: 
117: /**
118:  * Strip a parsed XHTML chapter to plain text. We deliberately avoid pulling
119:  * in a heavy DOM lib (jsdom): a small regex-driven scrub is enough for
120:  * theological prose. `<sup>`/`<ruby>` etc. become inline text, which is
121:  * fine for embedding — chunking will absorb the boundaries.
122:  */
123: function htmlToPlain(html: string): string {
124:   return (
125:     html
126:       // Remove script/style blocks entirely
127:       .replace(/<(script|style)[\s\S]*?<\/\1>/gi, '')
128:       // Convert <br> and block tags into newlines for paragraph boundaries
129:       .replace(/<br\s*\/?>/gi, '\n')
130:       .replace(/<\/(p|div|h[1-6]|li|tr|td|section|article|blockquote)>/gi, '\n')
131:       // Drop everything else
132:       .replace(/<[^>]+>/g, '')
133:       // Decode the handful of named entities that show up in real EPUBs
134:       .replace(/&nbsp;/g, ' ')
135:       .replace(/&amp;/g, '&')
136:       .replace(/&lt;/g, '<')
137:       .replace(/&gt;/g, '>')
138:       .replace(/&quot;/g, '"')
139:       .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(parseInt(n, 10)))
140:       .replace(/&#x([0-9a-fA-F]+);/g, (_, n) =>
141:         String.fromCharCode(parseInt(n, 16)),
142:       )
143:       // Collapse runs of whitespace
144:       .replace(/[ \t]+\n/g, '\n')
145:       .replace(/\n{3,}/g, '\n\n')
146:       .replace(/[ \t]{2,}/g, ' ')
147:       .trim()
148:   );
149: }
150: 
151: const epubExtractor: Extractor = {
152:   canHandle: (mime) => EPUB_MIMES.has(mime),
153:   async extract(buffer) {
154:     // The `epub2` API parses from a file path, not a buffer. We write the
155:     // bytes to a temp file scoped to this extraction and delete on exit.
156:     // Using a uuid avoids collisions when multiple Drive files are ingested
157:     // concurrently (the cron and a manual /ingest can overlap).
158:     const tmpPath = join(tmpdir(), `theosphere-${randomUUID()}.epub`);
159:     await fsp.writeFile(tmpPath, buffer);
160: 
161:     try {
162:       // Dynamic require — keeps the lib out of the build graph for envs
163:       // where Drive ingestion is disabled.
164:       // eslint-disable-next-line @typescript-eslint/no-require-imports
165:       const EPub = require('epub2').default ?? require('epub2');
166: 
167:       const book: any = await new Promise((resolve, reject) => {
168:         const epub = new EPub(tmpPath);
169:         epub.on('error', reject);
170:         epub.on('end', () => resolve(epub));
171:         epub.parse();
172:       });
173: 
174:       const chapters: string[] = [];
175:       // book.flow is the linear reading order; book.spine.contents is similar.
176:       // Some EPUBs only populate one of the two — fall through.
177: 
178:       const order: Array<{ id: string }> = book.flow?.length
179:         ? book.flow
180:         : (book.spine?.contents ?? []);
181: 
182:       for (const item of order) {
183:         try {
184:           const html: string = await new Promise((res, rej) => {
185:             book.getChapter(item.id, (err: Error | null, txt: string) => {
186:               if (err) rej(err);
187:               else res(txt);
188:             });
189:           });
190:           chapters.push(htmlToPlain(html));
191:         } catch {
192:           // Skip unreadable chapter — better partial than empty.
193:         }
194:       }
195: 
196:       const text = chapters.join('\n\n').trim();
197: 
198:       return {
199:         text,
200:         meta: {
201:           title:
202:             typeof book.metadata?.title === 'string'
203:               ? book.metadata.title
204:               : undefined,
205:           author:
206:             typeof book.metadata?.creator === 'string'
207:               ? book.metadata.creator
208:               : undefined,
209:           language:
210:             typeof book.metadata?.language === 'string'
211:               ? book.metadata.language
212:               : undefined,
213:         },
214:       };
215:     } finally {
216:       // Best-effort cleanup. Even if delete fails, OS will reclaim tmp.
217:       try {
218:         await fsp.unlink(tmpPath);
219:       } catch {
220:         /* ignore */
221:       }
222:     }
223:   },
224: };
225: 
226: /* ─── Registry ────────────────────────────────────────────────────────── */
227: 
228: const EXTRACTORS: ReadonlyArray<Extractor> = [
229:   pdfExtractor,
230:   docxExtractor,
231:   epubExtractor,
232: ];
233: 
234: export function findExtractor(mime: string): Extractor | undefined {
235:   return EXTRACTORS.find((e) => e.canHandle(mime));
236: }
237: 
238: /**
239:  * Remove a sujeira que a extração de PDF deixa no texto, antes do chunking.
240:  *
241:  * Motivo (30/07/2026): a biblioteca servia trechos citados com marcas de
242:  * paginação no meio — "conforme ensina -- 75 of 212 -- o apóstolo" — e com
243:  * palavras partidas pela hifenização de fim de linha ("justi- ficação").
244:  * Numa plataforma que exibe a citação ao usuário, isso é visível e passa a
245:  * impressão de que a obra está corrompida.
246:  *
247:  * O efeito colateral era pior: na análise de qualidade, três passagens
248:  * sorteadas caíam em blocos de marcas de página e o revisor condenava o livro
249:  * inteiro como ilegível. Onze obras boas — Owen, Schaeffer, Piper, o
250:  * comentário de Hodge à Confissão de Westminster — foram reprovadas assim
251:  * antes desta limpeza existir.
252:  *
253:  * Deliberadamente conservadora: só remove o que é inequivocamente artefato.
254:  * Normalização agressiva (pontuação, maiúsculas, quebras de parágrafo) faria
255:  * o chunking perder os limites semânticos em que ele se apoia.
256:  */
257: export function cleanExtractedText(text: string): string {
258:   return (
259:     text
260:       // Marcas que o pdf-parse insere entre páginas.
261:       .replace(/--\s*\d+\s*of\s*\d+\s*--/gi, ' ')
262:       .replace(/\bPage\s+\d+\s+of\s+\d+\b/gi, ' ')
263:       // Hifenização de fim de linha: "justi- ficação" → "justificação".
264:       // Exige espaço depois do hífen, para não colar palavras legitimamente
265:       // compostas ("porta-voz", "recém- nascido" quebrado vs. "recém-nascido").
266:       .replace(/(\p{L})-\s+(\p{L})/gu, '$1$2')
267:       // Espaços redundantes, preservando as quebras de parágrafo.
268:       .replace(/[ \t]{2,}/g, ' ')
269:       .replace(/\n{3,}/g, '\n\n')
270:   );
271: }
272: 
273: /**
274:  * Mime-type clause for the Google Drive `files.list` query. Keep this in
275:  * sync with the registered extractors above.
276:  */
277: export const SUPPORTED_MIME_QUERY = [
278:   "mimeType='application/pdf'",
279:   "mimeType='application/vnd.openxmlformats-officedocument.wordprocessingml.document'",
280:   "mimeType='application/epub+zip'",
281:   "mimeType='application/epub'",
282: ].join(' or ');
